/* Fit: fill the frame when the photo shape matches, otherwise show the whole photo on a soft blur of itself */
const FIT_T=.01;let fitRO=null;const fitSet=new Set();
function fitImg(el,frame,th){if(!el)return;frame=frame||el.parentElement;if(!frame)return;
 const go=()=>{const nw=el.naturalWidth||el.videoWidth||el._pw,nh=el.naturalHeight||el.videoHeight||el._ph,fw=frame.clientWidth,fh=frame.clientHeight;if(!nw||!nh||!fw||!fh)return;
  const ir=nw/nh,fr=fw/fh,crop=1-Math.min(ir,fr)/Math.max(ir,fr),c=crop>(th==null?FIT_T:Math.max(th,.03));
  el.classList.toggle('fit-in',c);frame.classList.toggle('amb',c);if(c)frame.style.setProperty('--amb','url("'+(el.tagName==='VIDEO'?(el.poster||el.currentSrc):(el.currentSrc||el.src))+'")')};
 el._fit=go;fitSet.add(el);
 if(el.tagName==='VIDEO'){if(el.poster){const pi=new Image();pi.onload=()=>{el._pw=pi.naturalWidth;el._ph=pi.naturalHeight;go()};pi.src=el.poster}el.readyState>=1?go():el.addEventListener('loadedmetadata',go,{once:true})}else{el.complete&&el.naturalWidth?go():el.addEventListener('load',go,{once:true})}
 if('ResizeObserver' in window){fitRO=fitRO||new ResizeObserver(es=>es.forEach(e=>{fitSet.forEach(x=>{if(!x.isConnected){fitSet.delete(x);return}if(x._fr===e.target)x._fit()})}));el._fr=frame;fitRO.observe(frame)}}
function fitAll(root,sel,th){(root||document).querySelectorAll(sel).forEach(i=>fitImg(i,null,th))}
