const PATHMAP=window.__P||{};
const keyNow=()=>location.hash.slice(1)||PATHMAP[(decodeURIComponent(location.pathname).split('/').filter(Boolean).pop()||'').replace(/\.html$/,'')]||'home';
const TITLES={home:'Boat Hire, Diving & Watersports in Latchi, Cyprus | Latchi Watersports Centre',boat:'Self-Drive Boat Hire in Latchi, Cyprus, No Licence Needed | Latchi Watersports',ch:'Private Yacht Charters in Latchi, Cyprus | Latchi Watersports Centre'};
function route(){
  const h=keyNow();lastURL=location.href;
  const DEEP={diving:'dive',rya:'rya',jetski:'jet',parasailing:'para',seabob:'seabob',sunset:'sunset',waterski:'ski',tube:'tube',paddleboards:'sup'};
  const INFO={story:1,sales:1,marine:1,jobs:1,blog:1,fishing:1,weddings:1,corporate:1};
  const PATHOPEN=!location.hash&&window.__P;
  if(PATHOPEN&&(INFO[h]||DEEP[h])&&window.openAct){$('#view-home').hidden=false;$('#view-boat').hidden=true;$('#view-charters').hidden=true;$('#top').classList.remove('always');closeMenu();openAct(INFO[h]?h:DEEP[h],null,true);onScroll();return}
  if(INFO[h]){$('#view-home').hidden=false;$('#view-boat').hidden=true;$('#view-charters').hidden=true;$('#top').classList.remove('always');closeMenu();if(location.hash)history.replaceState(null,'','#home');setTimeout(()=>{window.openAct&&openAct(h,null)},60);onScroll();return}
  if(h==='watersports'){$('#view-home').hidden=false;$('#view-boat').hidden=true;$('#view-charters').hidden=true;$('#top').classList.remove('always');closeMenu();requestAnimationFrame(()=>$('#activities')?.scrollIntoView());onScroll();return}
  if(DEEP[h]||h==='watersports'){$('#view-home').hidden=false;$('#view-boat').hidden=true;$('#view-charters').hidden=true;$('#top').classList.remove('always');closeMenu();
   const card=DEEP[h]?$('.acts>.card[data-act="'+DEEP[h]+'"]'):$('.acts>.card[data-act="jet"]');
   if(card){card.scrollIntoView({block:'center'});if(DEEP[h])setTimeout(()=>{window.openAct&&openAct(DEEP[h],card);if(location.hash)history.replaceState(null,'','#activities')},120);else{if(location.hash)history.replaceState(null,'','#activities');card.classList.add('ping');setTimeout(()=>card.classList.remove('ping'),1600)}}
   onScroll();return}
  const isBoat=h==='boat-hire'||h==='fleet'||h==='faq', isCh=h==='charters'||h==='yfleet';
  $('#view-home').hidden=isBoat||isCh;$('#view-boat').hidden=!isBoat;$('#view-charters').hidden=!isCh;
  $('#top').classList.toggle('always',isBoat||isCh);
  $('#abPrice').hidden=!isBoat;
  $$('.nav a').forEach(a=>a.toggleAttribute('aria-current',(isBoat&&a.getAttribute('href')==='#boat-hire')||(isCh&&a.getAttribute('href')==='#charters')));
  if(isBoat){ if(h==='boat-hire') window.scrollTo(0,0); else $('#'+h)?.scrollIntoView(); document.title=TITLES.boat}
  else if(isCh){ if(h==='charters') window.scrollTo(0,0); else $('#'+h)?.scrollIntoView(); document.title=TITLES.ch}
  else { const sl=(decodeURIComponent(location.pathname).split('/').filter(Boolean).pop()||'').replace(/\.html$/,'');document.title=(window.__TT&&window.__TT[sl])||TITLES.home; if(h==='home') window.scrollTo(0,0); else requestAnimationFrame(()=>$('#'+h)?.scrollIntoView()) }
  onScroll(); closeMenu();
}
let lastURL='';
const viewOf=h=>{h=h||'home';return (h==='boat-hire'||h==='fleet'||h==='faq')?'boat':(h==='charters'||h==='yfleet')?'ch':'home'};
const curView=()=>!$('#view-boat').hidden?'boat':!$('#view-charters').hidden?'ch':'home';
function goRoute(force){if(!force&&location.href===lastURL)return;const t=viewOf(keyNow());if(document.startViewTransition&&t!==curView()&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(()=>route());else route()}
