function trSeg(s,i){if(D[s])return D[s][i];let m;
 if(m=s.match(/^from (€[\d,.]+)$/))return W.from[i]+' '+m[1];
 if(m=s.match(/^up to (\d+)( guests)?$/i)){const t=W.upto[i]+' '+m[1]+(m[2]?' '+W.guest[i](m[1]):'');return s[0]==='U'?t[0].toUpperCase()+t.slice(1):t}
 if(m=s.match(/^(\d+) hours?$/))return m[1]+' '+W.hour[i](m[1]);
 if(m=s.match(/^(\d+) hrs?$/))return m[1]+' '+W.hr[i](m[1]);
 if(m=s.match(/^(\d+) min$/))return m[1]+' '+W.min[i](m[1]);
 if(m=s.match(/^(\d+) cabins?$/))return m[1]+' '+W.cabin[i](m[1]);
 if(m=s.match(/^(\d+) riders?$/))return m[1]+' '+W.rider[i](m[1]);
 if(m=s.match(/^(\d+) photos ›$/))return m[1]+' '+W.photo[i](m[1])+' ›';
 if(m=s.match(/^(€[\d,.]+)\/hr$/))return m[1]+'/'+W.hr[i](1);
 if(/^[\d ×or]+hp$/.test(s))return s.replace(' or ',' '+W.or[i]+' ').replace(/hp$/,' '+W.hp[i]);
 if(m=s.match(/^(.+) (€[\d,.]+) plus fuel$/))return m[1]+' '+m[2]+' '+W.fuel[i];
 if(m=s.match(/^(.+), (\d+ hours?)$/))return (D[m[1]]?D[m[1]][i]:m[1])+', '+trSeg(m[2],i);
 return null}
function tr(raw){if(LANG==='en')return raw;const i=LI[LANG];const s=raw.replace(/\s+/g,' ').trim();if(!s||!/[A-Za-z]/.test(s))return raw;
 let r=trSeg(s,i);if(r==null&&s.includes(' · '))r=s.split(' · ').map(p=>trSeg(p,i)??p).join(' · ');
 if(r==null||r===s)return raw;const lead=raw.match(/^\s*/)[0],tail=raw.match(/\s*$/)[0];return lead+r+tail}
const EN=new WeakMap(),OUT=new WeakMap();
function tNode(n){const p=n.parentNode;if(!p||/^(SCRIPT|STYLE|NOSCRIPT)$/.test(p.nodeName))return;const v=n.nodeValue;
 if(OUT.has(n)&&OUT.get(n)===v)return;EN.set(n,v);const o=tr(v);OUT.set(n,o);if(o!==v)n.nodeValue=o}
function tAttr(el){if(!el.hasAttribute||!el.hasAttribute('placeholder'))return;if(!el.dataset.enPh)el.dataset.enPh=el.placeholder;el.placeholder=tr(el.dataset.enPh)}
function tTree(root){if(root.nodeType===3){tNode(root);return}if(root.nodeType!==1&&root.nodeType!==9)return;
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode())tNode(n);
 if(root.querySelectorAll){tAttr(root);root.querySelectorAll('[placeholder]').forEach(tAttr)}}
function setLang(l,manual){LANG=LANGS.includes(l)?l:'en';document.documentElement.lang=LANG;$('#lang').value=LANG;
 // restore English on nodes we translated, then translate again
 const w=document.createTreeWalker(document.documentElement,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(EN.has(n)&&OUT.get(n)===n.nodeValue){n.nodeValue=EN.get(n);OUT.delete(n)}}
 tTree(document.documentElement);if(manual)store.set('lwc-lang',LANG)}
new MutationObserver(ms=>{if(LANG==='en')return;for(const m of ms){if(m.type==='characterData')tNode(m.target);else m.addedNodes.forEach(tTree)}}).observe(document.documentElement,{subtree:true,childList:true,characterData:true});
$('#lang').addEventListener('change',e=>setLang(e.target.value,true));
const deviceLang=()=>{for(const l of (navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||'en'])){const c=String(l).slice(0,2).toLowerCase();if(LANGS.includes(c))return c}return 'en'};
{const saved=store.get('lwc-lang');setLang(saved&&LANGS.includes(saved)?saved:deviceLang())}

/* ---------- Booking flow (3 steps) ---------- */
const ACT={boat:'Self-drive boat hire',yacht:'Yacht charter',dive:'Diving',jet:'Jet ski',para:'Parasailing',tube:'Banana & tube rides',ski:'Waterski & wakeboard',sup:'Paddleboard, canoe & pedalo',rya:'RYA course'};
const deposit=a=>a==='rya';
const itemsFor=a=>a==='boat'?FLEET:ITEMS[a];
let B={},step=1,lastFocus=null;
const drawer=$('#drawer'),scrim=$('#scrim');
function pickItem(act,g,id){const L=itemsFor(act);return (id&&L.find(x=>x.id===id))||L.find(x=>!x.guests||x.guests>=g)||L[0]}
function openBooking(o={}){
  lastFocus=document.activeElement;
  const act=o.act||'boat',g=o.guests||window.__bbGuests||2;const it=pickItem(act,g,o.boat);const noPick=act==='boat'&&!o.boat;
  const pd=o.date||($('#bb-date')&&$('#bb-date').value!==iso(tomorrow)?$('#bb-date').value:null);const d=pd?new Date(pd+'T12:00'):tomorrow;
  B={act,item:noPick?null:it.id,tier:o.tier!=null?o.tier:(act==='boat'?2:0),date:d,slot:null,guests:g,addons:{},name:'',email:'',phone:'',pay:'apple',dep:false,month:new Date(d.getFullYear(),d.getMonth(),1)};
  if(o.addon)B.addons[o.addon]=true;step=1;drawer.hidden=false;scrim.hidden=false;document.body.style.overflow='hidden';render();$('#drClose').focus();
}
function closeBooking(){const fin=()=>{drawer.classList.remove('out');scrim.classList.remove('out');drawer.hidden=true;scrim.hidden=true};document.body.style.overflow='';lastFocus?.focus();if(matchMedia('(prefers-reduced-motion: reduce)').matches||drawer.hidden){fin();return}drawer.classList.add('out');scrim.classList.add('out');setTimeout(fin,290)}
$('#drClose').addEventListener('click',closeBooking);scrim.addEventListener('click',closeBooking);
addEventListener('keydown',e=>{if(e.key==='Escape'){if(!drawer.hidden)closeBooking();else if(!sheet.hidden)closeMenu()}
  if(e.key==='Tab'&&!drawer.hidden){const f=$$('button:not([disabled]):not([hidden]),input,select,a[href],textarea',drawer).filter(x=>x.offsetParent);if(!f.length)return;const a=f[0],z=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}});
document.addEventListener('click',e=>{const o=e.target.closest('[data-open]');if(o&&window.openAct){e.preventDefault();openAct(o.dataset.open,null)}},true);
document.addEventListener('click',e=>{const t=e.target.closest('[data-book]');if(!t)return;e.preventDefault();const a=t.dataset.book||'boat';openBooking({act:a,boat:t.dataset.boat,guests,addon:t.dataset.addon})});

// Simulated availability: deterministic per date (live API in production)
function avail(d){const t=new Date(today.getFullYear(),today.getMonth(),today.getDate());if(d<t)return 'past';const n=(d.getDate()*7+d.getMonth()*3)%10;return n===0?'full':n<3?'lo':'hi'}
const SLOTS=['09:00','10:00','11:00','13:00','14:00','16:00'];
// Boats run in two daily slots: 09:00-13:00 and 14:00-18:00. Six hours runs 09:00-15:00. Short hires fit around them.
const slotsFor=()=>{if(B.act!=='boat')return SLOTS;const h=tierOf()[2];return h===4?['09:00–13:00','14:00–18:00']:h===6?['09:00–15:00']:h===2?['09:00','11:00','14:00','16:00']:['09:00','10:00','11:00','14:00','15:00','16:00','17:00']};
const slotOpen=(d,s,i)=>((d.getDate()+i*3)%5)!==0;
const fmt=d=>d.toLocaleDateString(loc(),{weekday:'short',day:'numeric',month:'short'});
const itemOf=()=>itemsFor(B.act).find(x=>x.id===B.item)||itemsFor(B.act)[0];
const tierOf=()=>{const it=itemOf();return it.tiers[Math.min(B.tier,it.tiers.length-1)]};
const eur=n=>'€'+(Math.round(n*100)/100).toLocaleString('en-GB',{minimumFractionDigits:n%1?2:0,maximumFractionDigits:2});
function lines(){const it=itemOf(),t=tierOf(),L=[];const mult=it.pp?Math.max(B.guests,it.min||1):1;
  L.push([`${it.name}, ${t[0].toLowerCase()}${mult>1?` × ${mult}`:''}`,t[1]==null?'req':t[1]*mult]);
  if((B.act==='boat'||B.act==='yacht')&&B.addons.seabob)L.push(['Seabob for 1 hour','req']);
  if(B.act==='boat'){const hrs=t[2];
    if(B.addons.toy)L.push(['Wakeboard, waterskis or tube',25]);
    if(B.addons.guide)L.push(hrs?[`Guide on board, ${hrs} h`,25*hrs]:['Guide on board, €25 per hour','day']);
    if(B.addons.snork)L.push([`Masks & snorkels × ${B.guests}`,2.5*B.guests]);}
  return L}
const total=()=>lines().reduce((s,l)=>s+(typeof l[1]==='number'?l[1]:0),0);
const reqOnly=()=>lines().every(l=>l[1]==='req');
const hasReq=()=>lines().some(l=>l[1]==='req');
