      <div><p class="dr-label">${B.date?fmt(B.date):'Pick a date'} · ${B.act==='boat'&&tierOf()[2]>=4?'slot':'start time'}</p><div class="slots" id="startSlots">${slotsFor().map((s,i)=>{const o=B.date&&slotOpen(B.date,s,i);return `<button type="button" class="slot-btn" data-s="${s}" ${o?'':'disabled'} aria-pressed="${B.slot===s}">${s}${o?'':'<small>Booked</small>'}</button>`}).join('')}</div></div>
