    $$('.day',body).forEach(b=>b.addEventListener('click',()=>{B.date=new Date(m.getFullYear(),m.getMonth(),+b.dataset.d,12);B.slot=null;render();$(`.day[data-d="${b.dataset.d}"]`)?.focus()}));
    $$('#startSlots .slot-btn',body).forEach(b=>b.addEventListener('click',()=>{B.slot=b.dataset.s;$$('#startSlots .slot-btn',body).forEach(x=>x.setAttribute('aria-pressed',x===b));updateFoot()}));
    $$('[data-t]',body).forEach(b=>b.addEventListener('click',()=>{B.tier=+b.dataset.t;if(B.act==='boat')B.slot=null;render();$(`[data-t="${b.dataset.t}"]`)?.focus()}));
    $$('input[name="d-item"]',body).forEach(r=>r.addEventListener('change',()=>{B.item=r.value;render();const f=$('#drBody .choice');if(f){const sc=$('#drBody');const top=f.parentElement.getBoundingClientRect().top-sc.getBoundingClientRect().top+sc.scrollTop-8;sc.scrollTo({top,behavior:reduce?'auto':'smooth'})}}));
    $('#d-fleet')?.addEventListener('click',closeBooking);$('#toYacht')?.addEventListener('click',()=>{B.act='yacht';B.item=pickItem('yacht',B.guests).id;B.tier=0;render()});
