      <div class="summary"><div><span>Reference</span><b class="tnum">${ref}</b></div><div><span>${itemOf().name} · ${tierOf()[0].toLowerCase()}</span><span>${B.slot}</span></div><div><span>Confirmation sent to</span><span>${B.email.replace(/[<>&"]/g,'')}</span></div></div>
